\begin{theorem}\label{theorem-1}
\lean{theorem_1}
\leanok
Let $X$ be a set with at most $\frac{q^{n+1}-q}{q-1}$ elements. If
$f_{1}, \ldots, f_{k} \in \mathrm{Map}(X,{\mathbb{F}_{q}})$ for some $k>n$ then there exist
$g_{1}, \ldots, g_{n} \in \mathrm{Span}(f_{1}, \ldots, f_{k})$ such that
$\mathrm{Z}(g_{1}, \ldots, g_{n})=\mathrm{Z}(f_{1}, \ldots, f_{k})$.
\end{theorem}

n40459.content:
\begin{proposition}\label{prop-2}
\lean{prop_1}
\leanok
For every field ${\mathbb{F}_{q}}$ and every positive integer $n$ there are a set $X_{n}$ of cardinality
$\frac{q^{n+1}-q}{q-1}+1$, and maps $f_{1}, \ldots, f_{n+1} \in \mathrm{Map}(X_{n},{\mathbb{F}_{q}})$ such that
$\mathrm{Z}(f_{1}, \ldots, f_{n+1})=\emptyset$ but $\mathrm{Z}(g_{1}, \ldots, g_{n})\ne \emptyset$
for any $g_{1}, \ldots, g_{n} \in \mathrm{Span}(f_{1}, \ldots, f_{n+1})$.
\end{proposition}

n40460.content:
\begin{corollary}\label{corollary-3}
\lean{corollary_2}
\leanok
Let $n > 0$ and let $\phi \colon \mathcal{F} \to \mathrm{Map}(\mathbb{A}^{n}({\mathbb{F}_{q}}),{\mathbb{F}_{q}})$ be a
homomorphism of vector spaces over ${\mathbb{F}_{q}}$. Any subset of $\mathbb{A}^{n}({\mathbb{F}_{q}})$ defined by some
members of $\mathcal{F}$ (i.e., the zero locus of their images via $\phi$) can be defined using
at most $n$ members of $\mathcal{F}$.
\end{corollary}

n40461.content:
\begin{corollary}\label{corollary-4}
\lean{corollary_3}
\leanok
\uses{theorem-1}
Let $n \ge 0$ and let $\phi \colon \mathcal{F} \to \mathrm{Map}(\mathbb{P}^{n}({\mathbb{F}_{q}}),{\mathbb{F}_{q}})$ be a
homomorphism of vector spaces over ${\mathbb{F}_{q}}$. Any nonempty subset of $\mathbb{P}^{n}({\mathbb{F}_{q}})$ defined by
some members of $\mathcal{F}$ (i.e., the zero locus of their images via $\phi$) can be defined
using at most $n$ members of $\mathcal{F}$.
\end{corollary}

