n40465.content:
\begin{lemma}\label{lemma-6}
\lean{matrix_rank_lemma}
\leanok
Let $\mathbb{K}$ be an arbitrary field. For any matrix $A \in M_{n, m}(\mathbb{K})$ where $n\le m$ there exist a
matrix $M \in M_{n, m}(\mathbb{K})$ in reduced row echelon form having the rank equal to $n$, and a matrix
$B \in M_{n, n}(\mathbb{K})$ such that $A=BM$.
\end{lemma}

n40468.content:
\begin{proof}[Proof of Corollary \ref{corollary-3}]
\leanok
\proves{corollary-3}
\uses{theorem-1}
For any positive integer $n$ we have $\frac{q^{n+1}-q}{q-1}\ge q^{n}=\left| \mathbb{A}^{n}({\mathbb{F}_{q}})\right|$.
Applying Theorem \ref{theorem-1} and some elementary algebra, we get the assertion.
\end{proof}

n40469.content:
\begin{remark}\label{remark-7}
\lean{remark_example}
\leanok
It has been suggested by the reviewer of this paper to include the following example to
demonstrate that although the bound $\frac{q^{n+1}-q}{q-1}\ge q^{n}$ used in the proof of
Corollary \ref{corollary-3} is rather crude, the result is sharp for any $q$. Consider the system of
$n$ polynomials $f_{i}(x_{1}, \ldots, x_{n})=x_{i}$. While
$\mathrm{Z}(f_{1}, \ldots, f_{k})=\left\lbrace \theta\right\rbrace$, any system of $n-1$
combinations of them has at least $q$ common zeros.
\end{remark}
